// gh-1341 — the flutter_app js_widget_runtime pin must resolve the
// flutter_js hostCall/capture channel fix.
//
// The flutter_js engine shipped a hand-maintained `_bridgeChannels` list
// that never learned `__jsr_host_call` / `__jsr_capture`: flutter_js drops
// messages on unregistered channels, so every `jsr.hostCall(...)` promise
// hung forever on JSC builds (iOS/macOS) — voxel-sandbox spun forever and
// fa-craft fell back to the legacy scene3d path (~2 FPS). Upstream fix:
// flutter_js_widget_runtime commit 9d57570, published as hosted 0.4.156
// (v0.4.156 = 9d57570 + the automated `[pub bump]` commit).
//
// pubspec.yaml's own override comment documents the end state: "pin the
// exact upstream commit until the hosted 0.4.154+ is out, then drop the
// override and let the constraint resolve hosted." Hosted 0.4.156 is out
// and IS the fix commit, so the git override must be GONE.
//
// Deliberately static asserts over the committed pubspec.yaml + pubspec.lock
// (the nightly_desktop_leg_guard_test.dart / ci_pub_get_retry_guard_test.dart
// pattern) so the guard runs without touching the network.
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

YamlMap loadPubspec(String path) =>
    loadYaml(File(path).readAsStringSync()) as YamlMap;

/// The first hosted version carrying the 9d57570 bridge-channel fix.
const minFixedVersion = '0.4.156';

int pubVersion(String v) {
  // Strip any prerelease/build suffix ("0.5.0-dev.1", "0.4.157+1") —
  // a suffixed version is >= its plain triple.
  final core = v.split('-').first.split('+').first;
  final parts = core.split('.').map(int.parse).toList();
  assert(parts.length == 3, 'unexpected pub version: $v');
  return (parts[0] << 20) | (parts[1] << 10) | parts[2];
}

void main() {
  group('pubVersion', () {
    test('parses a plain triple', () {
      expect(pubVersion('0.4.156'), pubVersion('0.4.156'));
    });

    test('tolerates a build-suffixed version', () {
      // "0.4.157+hotfix" is >= the plain 0.4.156 floor — must not throw.
      expect(
        pubVersion('0.4.157+hotfix'),
        greaterThanOrEqualTo(pubVersion('0.4.156')),
      );
    });

    test('tolerates a prerelease-suffixed version', () {
      // "0.5.0-dev.1" sorts against its plain triple, never FormatException.
      expect(pubVersion('0.5.0-dev.1'), pubVersion('0.5.0'));
    });

    test('a suffixed version equals its plain triple', () {
      expect(pubVersion('0.4.157+1'), pubVersion('0.4.157'));
=====
// gh-1441 — the Fa app must wire the bridge-owned voxel world into every
// JsonWidgetRenderer it builds.
//
// js_widget_runtime 0.4.156 renders a `voxel` node as the "Voxel world"
// placeholder (Icons.landscape) exactly when the renderer's `voxelWorld`
// is null (json_widget_renderer.dart `_voxel`). The runtime engine exposes
// its bridge-owned world (`JsWidgetEngine.voxelWorld`, js_widget_engine_
// wrapper.dart:77 — the JsWidgetBridge creates the world eagerly at start,
// js_widget_bridge.dart:134), but the Fa app constructed the renderer
// without `voxelWorld` at its construction sites, so fa-craft /
// voxel-sandbox resolved their voxel probes, uploaded chunk meshes — and
// the screen showed the placeholder.
//
// The first cut of this guard hardcoded the two surfaces known then and
// certified completeness it did not have — `app_tile_host.dart` (the
// launcher board tile) was a third live construction site rendering
// `engine.tree` without `voxelWorld:` (gh-1441 review, BLOCKING). The scan
// below is therefore DIRECTORY-WIDE: every `JsonWidgetRenderer(` in
// `flutter_app/lib` must pass `voxelWorld:`, so a fourth site can never
// silently escape.
//
// Deliberately static asserts over the committed sources (the
// jsr_host_call_pin_guard_test.dart / nightly_desktop_leg_guard_test.dart
// pattern) so the guard runs without the native JS bridge and blocks merge
// even when all widget/E2E suites are green (ticket REG-1).
import 'dart:io';

import 'package:test/test.dart';

/// The app source tree scanned for renderer constructions. Every `.dart`
/// file under it is in scope — a new surface (or a renderer moved outside
/// `apps/`) is picked up without touching this guard.
const rendererRoot = 'flutter_app/lib';

/// The construction sites gh-1441 knows about — the floor below fails red
/// if the scan stops finding them (tree moved/renamed, scanner broken),
